package com.example.chromareader;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

public final class ChromaDbExporter {

    // Change these two values when you want to use another database or output file.
    private static final String CHROMA_DB_DIRECTORY =
            "/Users/guttikonda/Desktop/training docs/crypto-kafka-rag-project/crypto_chroma_db";
    private static final String OUTPUT_JSON_FILE = "chroma-export.json";

    private static final String EXPORT_SQL = """
            WITH records AS (
                SELECT
                    c.name AS collection_name,
                    e.id AS row_id,
                    e.embedding_id,
                    MAX(CASE
                        WHEN em.key = 'chroma:document' THEN em.string_value
                    END) AS document,
                    json_group_object(
                        em.key,
                        CASE
                            WHEN em.string_value IS NOT NULL THEN em.string_value
                            WHEN em.int_value IS NOT NULL THEN em.int_value
                            WHEN em.float_value IS NOT NULL THEN em.float_value
                            WHEN em.bool_value IS NOT NULL THEN json(
                                CASE WHEN em.bool_value = 1 THEN 'true' ELSE 'false' END
                            )
                            ELSE NULL
                        END
                    ) FILTER (WHERE em.key NOT LIKE 'chroma:%') AS metadata
                FROM collections c
                JOIN segments s
                    ON s.collection = c.id
                   AND s.scope = 'METADATA'
                JOIN embeddings e ON e.segment_id = s.id
                LEFT JOIN embedding_metadata em ON em.id = e.id
                GROUP BY c.name, e.id, e.embedding_id
            )
            SELECT json_group_array(
                json_object(
                    'collection', collection_name,
                    'id', embedding_id,
                    'document', document,
                    'metadata', json(COALESCE(metadata, '{}'))
                )
            )
            FROM (
                SELECT * FROM records ORDER BY collection_name, row_id
            );
            """;

    private ChromaDbExporter() {
    }

    public static void main(String[] args) throws Exception {
        Path input = Path.of(CHROMA_DB_DIRECTORY).toAbsolutePath().normalize();
        Path database = Files.isDirectory(input) ? input.resolve("chroma.sqlite3") : input;
        Path output = Path.of(OUTPUT_JSON_FILE).toAbsolutePath().normalize();

        if (!Files.isRegularFile(database)) {
            throw new IllegalArgumentException("Chroma database not found: " + database);
        }

        Path outputParent = output.getParent();
        if (outputParent != null) {
            Files.createDirectories(outputParent);
        }

        export(database, output);
        System.out.println("Export complete: " + output);
    }

    private static void export(Path database, Path output) throws Exception {
        Process process;
        try {
            process = new ProcessBuilder(
                    "sqlite3",
                    "-readonly",
                    database.toString(),
                    EXPORT_SQL
            )
                    .redirectOutput(output.toFile())
                    .redirectError(ProcessBuilder.Redirect.INHERIT)
                    .start();
        } catch (IOException error) {
            throw new IllegalStateException(
                    "Could not start sqlite3. Install the sqlite3 command-line tool and try again.",
                    error
            );
        }

        int exitCode = process.waitFor();
        if (exitCode != 0) {
            Files.deleteIfExists(output);
            throw new IllegalStateException("sqlite3 export failed with exit code " + exitCode);
        }
    }
}
